import anthropic

client = anthropic.Anthropic(
    api_key="your-anthropic-api-key"
)

message = client.messages.create(
    model="claude-sonnet-4-20250514",
    max_tokens=1024,
    messages=[
        {"role": "user", "content": "Hello, what can you do?"}
    ]
)

print(message.content[0].text)
